// The director's #851 commons carve-out is GONE (#funnel-planning-moves-to-director). The commons are
// a worker STREAM with an owner, a branch and a worktree; the director is a scoped PLAN writer.
describe("director is a scoped plan writer, not a commons carve-out", () => {
  const WRITE_TOOLS = ["Edit", "Write", "NotebookEdit"]; // whole-tool deny set (no MultiEdit — removed tool, #3534)
  const COMMONS = [".gitignore", "package.json", "tsconfig.json", ".github/workflows/**", ".env.example"];

  it("no longer qualifies for a carve-out at all — it is code:write, not code:none", () => {
    expect(ROLE_DEFAULTS.director.code).toBe("write");
    expect(hasScopedWriteCarveOut(ROLE_DEFAULTS.director)).toBe(false);
    // ...and handing it commons globs does NOT resurrect one.
    expect(hasScopedWriteCarveOut(roleCapability("director", { writeGlobs: COMMONS }))).toBe(false);
  });

  it("writes the plan files and nothing else", () => {
    const d = ROLE_DEFAULTS.director;
    for (const p of ["goal.md", "phases.json", "prompts/api-kickoff.md", "discovery/stack.md"]) {
      expect(canWritePath(d, p), `director must write ${p}`).toBe(true);
    }
    for (const p of ["src/App.tsx", "src/auth/login.ts", "crates/kb/src/lib.rs"]) {
      expect(canWritePath(d, p), `director must NOT write ${p}`).toBe(false);
    }
  });

  it("cannot reach a linked repo's commons — the boundary is DEPTH, not the glob", () => {
    // Worth stating precisely, because `*.json` is broad enough to match `tsconfig.json` on its own.
    // What keeps the commons out of reach is that the director runs at the project HUB and a linked
    // repo is checked out one level down (`<hub>/<repo>/`) — and `*` is a NON-SLASH run, so a plan
    // glob cannot cross into a repo. The commons stream owns those paths.
    const d = ROLE_DEFAULTS.director;
    for (const p of ["web/package.json", "web/tsconfig.json", "api/.github/workflows/ci.yml", "web/src/App.tsx"]) {
      expect(canWritePath(d, p), `commons ${p} is not the director's`).toBe(false);
    }
    // Hub-level files that match neither plan glob stay denied outright.
    for (const p of [".gitignore", ".env.example"]) {
      expect(canWritePath(d, p), `${p} matches no plan glob`).toBe(false);
    }
  });

  it("the DB-owned plan state stays denied even inside its globs (deny > allow, #1070)", () => {
    // `*.json`/`*.md` would otherwise auto-approve plan state that plan.db owns.
    const rules = roleWriteRules(ROLE_DEFAULTS.director);
    expect(rules.deny.length).toBeGreaterThan(0);
    for (const f of DB_OWNED_PLAN_FILES) expect(rules.deny).toContain(`Edit(${f})`);
  });

  it("bscAgentPerms hands it the write tools scoped to the plan globs", () => {
    const p = bscAgentPerms(ROLE_DEFAULTS.director);
    expect(p.deny_tools).toEqual([]);
    expect(p.write_globs).toEqual(PLAN_WRITE_GLOBS);
  });

  it("a code:none triage/tester handed globs stays write-denied (no accidental carve-out)", () => {
    for (const role of ["triage", "tester", "reviewer"] as const) {
      const cap = roleCapability(role, { writeGlobs: COMMONS });
      expect(hasScopedWriteCarveOut(cap)).toBe(false);
      expect(roleWriteRules(cap).deny).toEqual(WRITE_TOOLS);
      expect(canWritePath(cap, ".gitignore")).toBe(false);
    }
  });
});

// #1555 — the documentor's prose-doc write carve-out: it keeps code:"none" (no feature-code writes)
// yet ships DOC_GLOBS BY DEFAULT, so it may write EXACTLY the prose docs (markdown + docs tree) and
// nothing else. It reads git/GitHub, mutates neither (push/PR are flow-governed), and is hard-blocked
// on every code path — mirroring the #851 director carve-out but active as-launched.
describe("documentor prose-doc carve-out (#1555)", () => {
  const documentor = ROLE_DEFAULTS.documentor;

  it("is a code:none role that reads git/GitHub and mutates neither", () => {
    expect(documentor.git).toBe("read");
    expect(documentor.github).toBe("read");
    expect(documentor.code).toBe("none");
    expect(documentor.net).toBe("read");
    // git/gh mutations are denied by default; the flow lifts push/PR (like a worker, #304).
    expect(checkCommand(documentor, "git commit -m x").allowed).toBe(false);
    expect(checkCommand(documentor, "git push").allowed).toBe(false);
    expect(checkCommand(documentor, "gh pr merge 5").allowed).toBe(false);
    expect(checkCommand(documentor, "git status").allowed).toBe(true);
    expect(checkCommand(documentor, "gh pr view 5").allowed).toBe(true);
  });

  it("has an ACTIVE carve-out as launched — it ships DOC_GLOBS by default (no assignment needed)", () => {
    expect(documentor.writeGlobs).toEqual(DOC_GLOBS);
    expect(documentor.writeGlobs.length).toBeGreaterThan(0);
    expect(hasScopedWriteCarveOut(documentor)).toBe(true); // unlike the director, active without an assignment
  });

  it("MAY write prose-doc paths — markdown (top-level + nested), the docs tree, README/CHANGELOG", () => {
    for (const p of [
      "README.md", "CHANGELOG.md", "CLAUDE.md", "docs/architecture.md", "docs/adr/0001-x.md",
      "src/features/planner/README.md", "packages/api/CHANGELOG.md",
    ]) {
      expect(canWritePath(documentor, p)).toBe(true);
    }
  });

  it("is HARD-BLOCKED writing any source/code path — the least-privilege boundary holds", () => {
    for (const p of [
      "src/App.tsx", "src/auth/login.ts", "crates/kb/src/lib.rs", "src-tauri/src/main.rs",
      "package.json", "Cargo.toml", ".claude/settings.json", "docs/gen.ts",
    ]) {
      expect(canWritePath(documentor, p)).toBe(false);
    }
  });

  it("roleWriteRules auto-approves the DOC_GLOBS (allow, no whole-tool deny) so doc writes don't prompt", () => {
    const rules = roleWriteRules(documentor);
    // The whole-tool deny is lifted (deny > allow would otherwise mask the per-glob allows).
    expect(rules.deny).toEqual([]);
    for (const g of DOC_GLOBS) {
      expect(rules.allow).toContain(`Edit(${g})`);
      expect(rules.allow).toContain(`Edit(${g})`);
    }
    expect(rules.allow).toHaveLength(DOC_GLOBS.length); // one Edit(glob) per doc glob (#3534)
  });

  it("scopeWriteGlobs hard-limits the documentor's writes to DOC_GLOBS (bsc-scope hook), no assignment needed", () => {
    expect(scopeWriteGlobs("documentor", [])).toEqual(DOC_GLOBS);
  });

  it("bscAgentPerms keeps the documentor's write tools scoped to DOC_GLOBS (carve-out active)", () => {
    const p = bscAgentPerms(documentor);
    expect(p.deny_tools).toEqual([]); // write_file/edit_file NOT denied — carve-out active
    expect(p.write_globs).toEqual(DOC_GLOBS);
    // git/gh writes stay denied unless the flow grants push/PR.
    expect(p.deny_bash).toContain("git push");
    expect(p.deny_bash).toContain("gh pr create");
    expect(bscAgentPerms(documentor, ["git push", "gh pr create"]).deny_bash).not.toContain("gh pr create");
  });

  it("does not spawn its own sub-agents restriction — only workers deny Task; documentor keeps it", () => {
    expect(roleDeniedTools(documentor)).toEqual([]);
  });
});

// #2471 — the designer role: the Design Studio's UI-kit session. `none` on every axis: kits live in
// the bsc store (not files), so there is nothing it should write, commit, publish, or fetch. Its one
// command surface (`bsc ui` + the deprecated `bsc component` alias) is granted at launch via the
// restricted allow-list (`restrictedAllow`, settings.rs), not by the role gate.
describe("designer role (#2471)", () => {
  const designer = ROLE_DEFAULTS.designer;

  it("is none on every axis except the kit store — no git, no GitHub, no code, no net; ui: write", () => {
    expect(designer.git).toBe("none");
    expect(designer.github).toBe("none");
    expect(designer.code).toBe("none");
    expect(designer.net).toBe("none");
    // The ONE write grant (#2470 integration): the designer is the sole ui:"write" role, so the
    // runtime scope doc lets it drive `bsc ui set/remove` where every other role is read-scoped.
    expect(designer.ui).toBe("write");
    // `graph: read` — the designer composes AGAINST the algorithms library and never redefines it;
    // that is the librarian's store, and the two studio sessions stay separable.
    expect(sessionScopes(designer)).toEqual({ graph: "read", ui: "write" });
    expect(designer.writeGlobs).toEqual(["scratch/**"]);   // #3373: the sealed staging dir, nothing else
  });

  it("roleDeniedCommands denies git AND gh outright (the whole tools) and nothing on the kit store", () => {
    const denies = roleDeniedCommands(designer);
    expect(denies).toContain("git");
    expect(denies).toContain("gh");
    // The `none` tiers deny the bare tool — the granular write-prefix lists are the read-tier form.
    expect(denies).not.toContain("git push");
    expect(denies).not.toContain("gh pr create");
    // ui:"write" — nothing on the KIT store is denied; the restricted allow-list (not the role gate)
    // is what narrows a confined role's surface.
    expect(denies.some((d) => d.startsWith("bsc ui") || d.startsWith("bsc component"))).toBe(false);
    // It is NOT true that the gate adds no `bsc` denies to a restricted role at all — this test used
    // to say so, and it only held for the designer by accident: `curator` has no `bsc request` on its
    // surface, so it already picks up the tooling-request deny (#4000). Persona writes are the second
    // such case (architect-only, epic `the-persona-is-the-whole-agent`), and they apply here too —
    // the confined allow-list is ignored under the bypass posture, where the hook is the only gate.
    expect(denies).toContain("bsc persona set");
  });

  it("roleDeniedTools denies the web tools (net:none) — no live injection surface", () => {
    expect(roleDeniedTools(designer)).toEqual(["WebFetch", "WebSearch"]);
  });

  // #3373 CHANGED THIS PROPERTY DELIBERATELY. The designer used to be write-denied through every path,
  // because kits live in the store, not in files. But a heredoc cannot be allow-listed (newlines are
  // command separators), so JSON-on-stdin — its ONLY authoring channel — was unusable, and the spec
  // forbade every alternative. It now stages a payload in a sealed `scratch/**` dir and applies it with
  // `bsc ui set --file <name>`.
  //
  // The carve-out is EXACTLY that dir. These assertions are the boundary: project code stays denied.
  it("writes ONLY its sealed scratch dir — project code is still denied through every path", () => {
    expect(hasScopedWriteCarveOut(designer)).toBe(true);
    expect(designer.writeGlobs).toEqual(["scratch/**"]);

    const rules = roleWriteRules(designer);
    // A carve-out emits per-glob ALLOWS and no whole-tool deny (deny > allow would mask the allows).
    expect(rules.deny).toEqual([]);
    expect(rules.allow).toEqual(["Edit(scratch/**)"]); // Edit(path) covers Write/NotebookEdit too (#3534)

    // The boundary itself: inside the scratch dir yes, anywhere else no.
    expect(canWritePath(designer, "scratch/kit.json")).toBe(true);
    expect(canWritePath(designer, "scratch/nested/kit.json")).toBe(true);
    expect(canWritePath(designer, "src/App.tsx")).toBe(false);
    expect(canWritePath(designer, "CLAUDE.md")).toBe(false);          // its own spec
    expect(canWritePath(designer, ".claude/settings.json")).toBe(false); // its own permissions
    expect(canWritePath(designer, "kit.json")).toBe(false);           // workspace root, not scratch
  });

  it("the carve-out cannot be widened by handing it broader globs", () => {
    // A stale/edited config-dir override must not be able to turn the scratch carve-out into a general
    // write grant without also changing `code`, which the role table pins to "none".
    const wide = roleCapability("designer", { writeGlobs: ["**"] });
    expect(canWritePath(wide, "src/App.tsx")).toBe(true);  // globs ARE authoritative once carved out…
    // …so the real guard is that the SHIPPED role's globs are exactly the scratch dir, asserted above,
    // and that `code` stays "none" so no implicit write tier exists.
    expect(designer.code).toBe("none");
    expect(ROLE_DEFAULTS.designer.writeGlobs).toEqual(["scratch/**"]);
  });

  it("checkCommand blocks every git/gh invocation, reads included", () => {
    expect(checkCommand(designer, "git status").allowed).toBe(false);
    expect(checkCommand(designer, "git push").allowed).toBe(false);
    expect(checkCommand(designer, "gh issue list").allowed).toBe(false);
    expect(checkCommand(designer, "gh pr create -t x").allowed).toBe(false);
    // Non-git/gh commands pass this gate — the restricted allow-list is what narrows them to bsc ui.
    expect(checkCommand(designer, "bsc ui schema").allowed).toBe(true);
  });

  it("bscAgentPerms renders the same wall for the bsc-agent runtime", () => {
    const p = bscAgentPerms(designer);
    // #3373: the scratch carve-out mirrors here too — the write tools are available, scoped to the
    // one staging dir. A divergence between the runtimes would mean the same role is confined
    // differently depending on which shell drives it.
    expect(p.deny_tools).toEqual([]);
    expect(p.write_globs).toEqual(["scratch/**"]);
    expect(p.deny_bash).toContain("git");
    expect(p.deny_bash).toContain("gh");
    expect(p.deny_bash).toContain("cp");   // shell mutation stays denied despite the carve-out
  });
});

// #2755 — the architect role: the Teams Studio's team-authoring session. `none` on EVERY axis, `ui`
// included (unlike the designer's ui:"write" — it never touches the UI-kit store). Its one command
// surface (`bsc teams` + `bsc persona`) is granted at launch via the restricted allow-list
// (`restrictedAllow`, settings.rs), not by the role gate. The Teams graph stays the read-only viewer.
describe("architect role (#2755)", () => {
  const architect = ROLE_DEFAULTS.architect;

  it("is none on EVERY axis — no git, no GitHub, no code, no net, and ui:none (not a UI-kit session)", () => {
    expect(architect.git).toBe("none");
    expect(architect.github).toBe("none");
    expect(architect.code).toBe("none");
    expect(architect.net).toBe("none");
    expect(architect.ui).toBe("none");
    expect(sessionScopes(architect)).toEqual({ graph: "none", ui: "none" });
    expect(architect.writeGlobs).toEqual(["scratch/**"]);   // #3373: the sealed staging dir, nothing else
  });

  it("roleDeniedCommands denies git, gh, AND the ui-kit store (bsc ui + the alias) outright", () => {
    const denies = roleDeniedCommands(architect);
    expect(denies).toContain("git");
    expect(denies).toContain("gh");
    // ui:"none" denies the whole `bsc ui` tool (and its deprecated `bsc component` alias) — the
    // architect never edits UI kits; that's the designer's job.
    expect(denies).toContain("bsc ui");
    expect(denies).toContain("bsc component");
    // The `none` tiers deny the bare tool — the granular write-prefix lists are the read-tier form.
    expect(denies).not.toContain("git push");
    expect(denies).not.toContain("gh pr create");
    expect(denies).not.toContain("bsc ui set"); // subsumed by the whole-tool deny, not emitted redundantly
    // Its OWN surface (bsc teams / bsc persona) is not role-gate-denied — it's granted via restrictedAllow.
    expect(denies).not.toContain("bsc teams");
    expect(denies).not.toContain("bsc persona");
  });

  it("roleDeniedTools denies the web tools (net:none) — no live injection surface", () => {
    expect(roleDeniedTools(architect)).toEqual(["WebFetch", "WebSearch"]);
  });

  // #3373, same change as the designer: teams/personas still live in the stores, but the architect
  // needs a place to STAGE the JSON it applies with `bsc teams set --file <name>`, because a heredoc
  // cannot be allow-listed. The carve-out is exactly that sealed dir.
  it("writes ONLY its sealed scratch dir — project code is still denied through every path", () => {
    expect(hasScopedWriteCarveOut(architect)).toBe(true);
    expect(architect.writeGlobs).toEqual(["scratch/**"]);

    const rules = roleWriteRules(architect);
    expect(rules.deny).toEqual([]);
    expect(rules.allow).toEqual(["Edit(scratch/**)"]); // Edit(path) covers Write/NotebookEdit too (#3534)

    expect(canWritePath(architect, "scratch/team.json")).toBe(true);
    expect(canWritePath(architect, "src/App.tsx")).toBe(false);
    expect(canWritePath(architect, "CLAUDE.md")).toBe(false);
  });

  // The carve-out grants the write TOOLS on one dir; it must NOT un-deny file-mutating SHELL commands.
  // `roleDeniedCommands` lifts those for a carve-out role (the director writes its commons with bash),
  // so a restricted role is explicitly excluded — its spec says in as many words not to reach for bash
  // to sidestep the file rules, and its whole shell surface is one store CLI.
  it("still denies the file-mutating shell commands despite having a carve-out", () => {
    for (const cap of [ROLE_DEFAULTS.designer, ROLE_DEFAULTS.architect]) {
      const denies = roleDeniedCommands(cap);
      for (const cmd of ["tee", "cp", "mv", "sed -i", "dd", "vim"]) {
        expect(denies).toContain(cmd);
      }
    }
    // Contrast: the director's carve-out IS shell-written, so it keeps them.
    const commonsDirector = roleCapability("director", { writeGlobs: ["*.md"] });
    expect(roleDeniedCommands(commonsDirector)).not.toContain("cp");
  });

  it("checkCommand blocks every git/gh invocation, reads included", () => {
    expect(checkCommand(architect, "git status").allowed).toBe(false);
    expect(checkCommand(architect, "git push").allowed).toBe(false);
    expect(checkCommand(architect, "gh issue list").allowed).toBe(false);
    expect(checkCommand(architect, "gh pr create -t x").allowed).toBe(false);
    // Non-git/gh commands pass this gate — the restricted allow-list narrows them to bsc teams/persona.
    expect(checkCommand(architect, "bsc teams list").allowed).toBe(true);
    expect(checkCommand(architect, "bsc persona list").allowed).toBe(true);
  });

  it("bscAgentPerms renders the same wall for the bsc-agent runtime", () => {
    const p = bscAgentPerms(architect);
    expect(p.deny_tools).toEqual([]);            // #3373 scratch carve-out, mirrored from the Claude side
    expect(p.write_globs).toEqual(["scratch/**"]);
    expect(p.deny_bash).toContain("git");
    expect(p.deny_bash).toContain("gh");
    expect(p.deny_bash).toContain("bsc ui"); // ui:none flows through to the agent runtime too
    expect(p.deny_bash).toContain("cp");     // shell mutation stays denied despite the carve-out
  });
});

describe("restrictedRoleCommands (curator store surface, #3095)", () => {
  const LOOP = ["bsc loop new", "bsc loop say", "bsc loop watch", "bsc loop show", "bsc loop list"];

  it("hands the curator its two store CLIs — bsc ui (components) + bsc graph (algorithms)", () => {
    expect(restrictedRoleCommands("curator")).toEqual(["bsc ui", "bsc graph", "bsc persona whatami"]);
  });

  // The standing studio sessions' confinement now lives on the ROLE — it used to be pinned inside each
  // bespoke launch hook, so the SAME role produced a much wider gate on any other launch path. These
  // literals are the EXACT surfaces those hooks passed: a change here widens (or narrows) a
  // deliberately-confined session, so they are asserted verbatim rather than derived.
  it("pins each standing studio session's whole surface, byte-identical to its old launch hook", () => {
    // #a-studios-floor-denies-what-its-charter-instructs appends three to every studio: the ask its
    // charter tells it to make, the request READ to go with the write it already had, and the
    // self-identification verb. Per-VERB, never the bare noun — `bsc session` (start/stop) and
    // `bsc persona` (rewriting identities) stay the architect's alone.
    expect(restrictedRoleCommands("designer")).toEqual(
      ["bsc ui", "bsc component", "bsc shot preview", ...LOOP, "bsc request new", "bsc request list",
       "bsc session ask", "bsc session reply", "bsc request get", "bsc persona whatami"]);
    // #4090 added the two component READ verbs — enumerated, never the `bsc ui` prefix (which would also
    // auto-run `set`/`remove`, the designer's store).
    expect(restrictedRoleCommands("librarian")).toEqual(
      ["bsc graph", "bsc ui list", "bsc ui get", "bsc request new", "bsc request list",
       "bsc session ask", "bsc session reply", "bsc request get", "bsc persona whatami"]);
    // `bsc plan brief` (#funnel-generalize-brief-channel) is the architect's ONE outbound channel —
    // the tier-to-tier brief to a director. It is the bsc VERB rather than the `bsc-brief` shell
    // helper precisely so this surface stays all-`bsc `, which the interpreter test below pins.
    // #architect-sees-director-state adds the READ of its own tier: the full verb, so the grant
    // cannot expand to `bsc fleet wake` and hand the architect a lever to START a director.
    // #architect-starts-and-stops-system-sessions adds `bsc session` — start/stop/list over the
    // app's OWN studios. Safe on a prose-ingesting session because the verb's argument is an id from a
    // closed app-owned registry, not a command or a path; see the grant's comment in roleModel.ts.
    // The architect's surface after the whole epic. FOUR grants landed on it, each the FULL verb:
    //  · #architect-creates-a-director-with-discovery replaced the plural READ with the SINGULAR
    //    `bsc fleet director`, which adds `director new` (`directors` needs its OWN grant — see the prefix note in architectDocs.test.ts).
    //  · #architect-starts-and-stops-system-sessions added `bsc session`.
    //  · #architect-starts-a-new-project added `bsc project new`.
    //  · #architect-wires-project-relationships added `bsc project link` (create/modify/remove a
    //    contract) + `bsc project list` (the read it needs to wire one without guessing an id).
    //  · #architects-own-projects added `bsc project architect` — which architect OWNS a project. It
    //    is the ONLY surface that sets it (there is no picker in the UI), so an absent grant would
    //    leave the feature with no way to be used at all.
    expect(restrictedRoleCommands("architect")).toEqual(["bsc teams", "bsc persona", "bsc plan brief", "bsc plan requirement", "bsc plan classify", "bsc fleet director", "bsc fleet directors", "bsc session", "bsc project new", "bsc project link", "bsc project architect", "bsc project list", "bsc request new", "bsc request list", "bsc request get"]);
    // The two prefix boundaries that must hold, asserted separately: the array equality above would
    // still pass if an entry were merely REPLACED by its wider form.
    //
    // A bare `bsc project` would auto-run every project lifecycle verb (published/triaged/db) across
    // every project, not just the three the architect holds.
    expect(restrictedRoleCommands("architect")).not.toContain("bsc project");
    // A bare `bsc fleet` would carry `bsc fleet wake` — the DIRECTOR's lever over a worker, one tier
    // below where this session belongs. An architect reaching past its director is back in the middle
    // of a fleet it does not run.
    expect(restrictedRoleCommands("architect")).not.toContain("bsc fleet");
    expect(restrictedRoleCommands("architect")).not.toContain("bsc fleet wake");
    // NOT proof the read resolves — a grant is not a string prefix; architectDocs.test.ts pins the real rule.
    expect("bsc fleet directors".startsWith("bsc fleet director")).toBe(true);
    expect("bsc fleet wake".startsWith("bsc fleet director")).toBe(false);     // the wake still does not
    expect(restrictedRoleCommands("sound-designer")).toEqual(["bsc sound", "bsc request new", "bsc request list", "bsc session ask", "bsc session reply", "bsc request get", "bsc persona whatami"]);
  });

  // #architect-wires-project-relationships — the architect creates, removes AND modifies the contracts
  // between projects. Grants are prefix matches expanded to `Bash(<cmd> *)`, so what a grant actually
  // reaches is a question about strings; these assert BOTH directions of that, because the array
  // equality above proves the entry is present and proves nothing about what it covers.
  it("gives the architect every project-relationship verb, and no other project verb (#architect-wires-project-relationships)", () => {
    const surface = restrictedRoleCommands("architect");
    // All four link verbs resolve through the one grant — create, modify and remove included, which is
    // the whole point: a grant that reached only `list` would leave the wiring unchanged.
    for (const verb of ["bsc project link list", "bsc project link add", "bsc project link set", "bsc project link remove"]) {
      expect(surface.some((c) => verb.startsWith(c)), `${verb} must be auto-runnable`).toBe(true);
    }
    // It can see what it is wiring — without this the spec's discover-before-you-change rule is
    // unfollowable and the architect would be inventing project keys.
    expect(surface).toContain("bsc project list");

    // #architects-own-projects — all three ownership verbs resolve through the one grant. `set` is the
    // load-bearing one: it is how a project is split onto a named architect, and nothing else anywhere
    // can do it.
    for (const verb of ["bsc project architect list", "bsc project architect set", "bsc project architect clear"]) {
      expect(surface.some((c) => verb.startsWith(c)), `${verb} must be auto-runnable`).toBe(true);
    }
    // Naming needs no new grant — `bsc persona` is already held, and `rename` resolves through it.
    expect("bsc persona rename".startsWith("bsc persona")).toBe(true);
    expect(surface).toContain("bsc persona");

    // …and the lifecycle verbs stay out. `published`/`triaged` mark a project's state and `db` rewrites
    // its durable row — none of which is a relationship between two of them.
    for (const verb of ["bsc project published set", "bsc project triaged clear", "bsc project db remove"]) {
      expect(surface.some((c) => verb.startsWith(c)), `${verb} must NOT be auto-runnable`).toBe(false);
    }
    // The classic prefix trap, pinned as strings so it cannot be re-introduced by "simplifying" the
    // three grants into one: `bsc project` would reach every verb above.
    expect("bsc project db remove".startsWith("bsc project link")).toBe(false);
    expect("bsc project db remove".startsWith("bsc project")).toBe(true);
  });

  // #4090 — the librarian may LOOK UP a component and may never write one. Both halves are load-bearing
  // and they come from different mechanisms, so both are asserted here: the grant table governs AUTO-RUN
  // (so `bsc ui list`/`get` run without a prompt) while `ui: "read"` -> UI_WRITE_DENY is what actually
  // keeps writes out — per #4000 a grant that is merely absent does not gate anything, since `bsc` sits
  // in the permission model's always-allowed mandatory tier.
  it("lets the librarian READ the component store and never write it (#4090)", () => {
    const cmds = restrictedRoleCommands("librarian");
    expect(cmds).toContain("bsc ui list");
    expect(cmds).toContain("bsc ui get");
    // The bare prefix would expand to `Bash(bsc ui *)` and auto-run the mutating verbs too.
    expect(cmds).not.toContain("bsc ui");
    expect(cmds).not.toContain("bsc component");

    const denies = roleDeniedCommands(ROLE_DEFAULTS.librarian);
    for (const verb of ["bsc ui set", "bsc ui remove", "bsc ui kit set", "bsc ui kit remove"]) {
      expect(denies).toContain(verb);
    }
    // ...and the deny must not be so broad that it swallows the reads it was paired with (deny > allow).
    expect(denies).not.toContain("bsc ui");
    expect(denies).not.toContain("bsc ui list");
    expect(denies).not.toContain("bsc ui get");
  });

  // ONLY THE DESIGNER is a loop participant now (#the-loop-comes-out-an-ask-is-just-a-delivery). Every
  // studio used to hold these verbs because `bsc session ask` reached them THROUGH a loop; it delivers
  // directly now, so the grant had no remaining use anywhere but the overnight design run — the one
  // loop consumer that measurably works (3 loops, 21 turns, against 20 ask loops with 0).
  it("gives the DESIGNER the loop participant verbs, and no other studio", () => {
    expect(restrictedRoleCommands("designer")).toEqual(expect.arrayContaining(LOOP));
    for (const role of ["curator", "librarian", "architect", "sound-designer", "integrator"] as const) {
      const cmds = restrictedRoleCommands(role);
      for (const verb of LOOP) {
        expect(cmds, `${role} no longer needs ${verb} — an ask is delivered, not routed through a loop`)
          .not.toContain(verb);
      }
    }
  });

  // `bsc loop stop` is the ONLY way to halt an `--until false` loop, and the CLI withholds it from
  // participants by design ("a separate verb from `say`, so a participant cannot reach it"). The bare
  // `"bsc loop"` prefix used to grant it: it expands to `Bash(bsc loop *)`, which matches `bsc loop stop`
  // — so a session could end the infinite loop it exists to run. Halting stays outside the conversation.
  it("never grants `bsc loop stop` — a participant cannot halt its own loop", () => {
    for (const role of ["curator", "designer", "librarian", "architect", "sound-designer", "integrator", "operator"] as const) {
      const cmds = restrictedRoleCommands(role);
      expect(cmds).not.toContain("bsc loop stop");
      // The bare prefix is what silently re-grants `stop` via the `Bash(<cmd> *)` rule — it must not return.
      expect(cmds).not.toContain("bsc loop");
    }
  });

  // #3369: `sound-designer` shares a WORD with `designer` but is a DISTINCT role. Any lookup that
  // matched loosely (startsWith / includes / a stripped hyphen) would hand one session the other's
  // surface — the sound-designer would gain `bsc ui` + the whole Design Studio toolbelt, or the
  // designer would lose it. Pinned in both directions.
  it("never conflates `designer` with `sound-designer` — the names overlap, the surfaces do not", () => {
    const designer = restrictedRoleCommands("designer");
    const sound = restrictedRoleCommands("sound-designer");
    // The exact surface is pinned in the verbatim test above; here the property is what matters —
    // the two roles share a word, never a store.
    expect(sound).toContain("bsc sound");
    expect(designer).not.toContain("bsc sound");
    expect(sound).not.toContain("bsc ui");
    expect(sound).not.toContain("bsc component");
    // ...and their capabilities differ: the designer is the one `ui: write` role (#2470/#2471).
    expect(ROLE_DEFAULTS.designer.ui).toBe("write");
    expect(ROLE_DEFAULTS["sound-designer"].ui).toBe("none");
  });

  it("is empty for every unrestricted role and for an absent role", () => {
    // `steward` joins the restricted set: like the architect and the designer, its `allow` list IS its
    // whole auto-runnable surface, so the baseline build tiers (cargo/npm/python) are suppressed and
    // every mutating verb falls through to a prompt rather than auto-running.
    const restricted = new Set<SessionRole>(["curator", "designer", "librarian", "architect", "sound-designer", "integrator", "operator", "steward"]);
    for (const role of Object.keys(ROLE_DEFAULTS) as SessionRole[]) {
      if (restricted.has(role)) continue;
      expect(restrictedRoleCommands(role)).toEqual([]);
    }
    expect(restrictedRoleCommands(null)).toEqual([]);
    expect(restrictedRoleCommands(undefined)).toEqual([]);
  });

  it("isRestrictedRole marks exactly the confined roles — they must never be flipped to bypass", () => {
    for (const role of ["curator", "designer", "librarian", "architect", "sound-designer", "integrator", "operator"] as SessionRole[]) {
      expect(isRestrictedRole(role)).toBe(true);
    }
    for (const role of ["worker", "director", "planner", "triage", "reviewer"] as SessionRole[]) {
      expect(isRestrictedRole(role)).toBe(false);
    }
    expect(isRestrictedRole(null)).toBe(false);
    expect(isRestrictedRole(undefined)).toBe(false);
  });

  // #3373: the scratch carve-out lets a restricted session write arbitrary bytes to disk. That is only
  // safe because NOTHING it can auto-run will execute them — its whole surface is one store CLI, which
  // reads the file and JSON-parses it. Today that holds by accident of the allow-list's contents; this
  // asserts it, so a future widening cannot quietly turn a staging dir into an execution path.
  it("no restricted role can auto-run an interpreter — a staged file can never be executed", () => {
    const EXECUTORS = ["bash", "sh", "zsh", "node", "python", "python3", "perl", "ruby", "chmod", "./", "source", "eval"];
    for (const role of ["designer", "architect", "librarian", "sound-designer", "curator"] as SessionRole[]) {
      const surface = restrictedRoleCommands(role);
      expect(surface.length).toBeGreaterThan(0);
      for (const cmd of EXECUTORS) {
        expect(surface.some((c) => c === cmd || c.startsWith(`${cmd} `))).toBe(false);
      }
      // Every granted command is a `bsc` store verb — nothing else is on the surface at all.
      for (const c of surface) expect(c.startsWith("bsc ")).toBe(true);
    }
  });

  it("returns a fresh array each call so callers can spread/mutate without corrupting the source", () => {
    const a = restrictedRoleCommands("curator");
    a.push("bsc plan");
    expect(restrictedRoleCommands("curator")).toEqual(["bsc ui", "bsc graph", "bsc persona whatami"]);
  });
});

describe("the global tooling-request queue is denied to project roles (#4000)", () => {
  // `bsc` is in the permission model's `mandatory` tier — ALWAYS allowed, every role, every posture.
  // So `bsc request` is reachable from any session that can run bash, and NOT granting it is not
  // enough: only an explicit deny keeps a project worker out of the queue a full-capability session
  // drains to edit base-studio-code itself.
  // #4001: the DIRECTOR is deliberately no longer in this list — it is the sanctioned escalation
  // point, and is safe to trust with it because `code: none` means it can ask for an app change but
  // never make one. Every other project role stays denied.
  const PROJECT_ROLES = ["worker", "triage", "planner", "reviewer", "documentor"] as const;

  it.each(PROJECT_ROLES)("denies %s the tooling queue", (role) => {
    expect(roleDeniedCommands(roleCapability(role))).toContain(TOOLING_REQUEST_COMMAND);
  });

  it("does NOT deny the roles that legitimately file tooling requests", () => {
    // These are granted `bsc request new` via RESTRICTED_ROLE_COMMANDS; denying it would break the
    // designer->debug channel (#3298) that the whole store exists for.
    for (const role of ["designer", "librarian", "sound-designer", "architect"] as const) {
      expect(roleDeniedCommands(roleCapability(role))).not.toContain(TOOLING_REQUEST_COMMAND);
    }
  });

  it("lets the director escalate, which is what keeps the worker lane closed (#4001)", () => {
    // A worker files a PROJECT request; the director promotes a genuine tooling gap by filing here.
    // Without this the two-lane design has no exit and a real tooling problem would be stuck.
    expect(mayFileToolingRequest("director")).toBe(true);
    expect(roleDeniedCommands(roleCapability("director"))).not.toContain(TOOLING_REQUEST_COMMAND);
    // …and the worker still cannot, which is the boundary that matters.
    expect(mayFileToolingRequest("worker")).toBe(false);
  });

  it("does not deny the debugger, which is the queue's consumer", () => {
    // It reads/claims/resolves. It has no RESTRICTED_ROLE_COMMANDS entry because it launches
    // full-capability rather than confined, so it is the one role the derivation names explicitly.
    expect(mayFileToolingRequest("debugger")).toBe(true);
  });

  it("derives the allow-list from the grants, so the two cannot drift", () => {
    // The property that keeps this maintainable: a role may file iff it is GRANTED the command.
    // Add the grant to a role and its deny lifts automatically; remove it and the deny returns.
    for (const role of ["designer", "architect"] as const) {
      expect(restrictedRoleCommands(role).some((c) => c.startsWith(TOOLING_REQUEST_COMMAND))).toBe(true);
      expect(mayFileToolingRequest(role)).toBe(true);
    }
    expect(mayFileToolingRequest("worker")).toBe(false);
    expect(mayFileToolingRequest(null)).toBe(false);
  });

  it("uses a pattern the deny matcher treats as a phrase, not a program name", () => {
    // Load-bearing: `deny_matches` matches a BARE program name against the program token, but keeps
    // substring semantics for anything containing other characters. A bare "bsc" would have denied
    // the entire CLI — every store, every session. The space is what scopes it to the one subcommand.
    expect(TOOLING_REQUEST_COMMAND).toContain(" ");
    expect(TOOLING_REQUEST_COMMAND).toBe("bsc request");
  });
});

// The persona floors ARE the role capability table (epic `the-persona-is-the-whole-agent`).
//
// ⚠️ THIS FILE USED TO ASSERT PARITY BETWEEN TWO SOURCES, AND THAT TEST IS NOW A TAUTOLOGY.
// It compared each packaged persona's `floor` against `ROLE_DEFAULTS` — which was built from
// `data/permissions/role-capabilities.json`. That file is deleted and `ROLE_DEFAULTS` is now DERIVED
// from these very floors, so the old assertion compares a value to itself and can never fail. Rather
// than delete the file and lose the coverage, the assertions were rewritten around the properties that
// are still falsifiable now that there is one source instead of two.
//
// The "did the table change" guard moved to `roleCapabilityBaseline.test.ts`, which pins the derived
// table against a frozen fixture — an independent copy, so it can actually fail.
import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, restrictedRoleCommands, type SessionRole } from "@/shared/lib/session/sessionRoles";
import type { PersonaFloor } from "@/features/personas/lib/persona";

/** The packaged persona defs, straight off disk — NOT `BUILTIN_PERSONAS`, which applies the config-dir
 *  overlay and would let a local mirror mask a drifted packaged floor. */
const packaged = import.meta.glob<{ id: string; role: SessionRole; floor?: PersonaFloor }>(
  "@data/personas/*.json",
  { eager: true, import: "default" },
);
const entries = Object.entries(packaged);

describe("the persona floors are the role capability table", () => {
  it("has personas to check — the glob still resolves", () => {
    expect(entries.length).toBeGreaterThan(0);
  });

  it("every packaged persona carries a floor", () => {
    // Not cosmetic: `ROLE_DEFAULTS` is projected from these, and a role that no persona supplies is
    // `undefined` at lookup. The module's own #2325 comment records what that costs — a module-load
    // `TypeError reading writeGlobs` that takes down the whole UI, not a quiet degradation.
    const missing = entries.filter(([, p]) => !p.floor).map(([path]) => path);
    expect(missing).toEqual([]);
  });

  it("supplies a floor for EVERY role in the union, so no lookup can be undefined", () => {
    const covered = new Set(entries.filter(([, p]) => p.floor).map(([, p]) => p.role));
    const uncovered = (Object.keys(ROLE_DEFAULTS) as SessionRole[]).filter((r) => !covered.has(r));
    expect(uncovered).toEqual([]);
  });

  it("projects each floor into ROLE_DEFAULTS without dropping a field", () => {
    // Falsifiable despite the shared source: it is the PROJECTION being checked (tableFromPersonas),
    // not the values. A projection that silently omitted `harvestRoots`, or that let a second persona
    // on the same role overwrite the first, fails here.
    for (const [path, p] of entries) {
      if (!p.floor) continue;
      const cap = ROLE_DEFAULTS[p.role];
      expect(cap, `${path}: role '${p.role}' has no capability row`).toBeTruthy();
      for (const axis of ["github", "git", "code", "net", "ui"] as const) {
        expect(cap[axis], `${path}: ${axis}`).toBe(p.floor[axis]);
      }
    }
  });

  it("exposes a floor's confined surface through restrictedRoleCommands", () => {
    // The `allow` list moved out of the RESTRICTED_ROLE_COMMANDS const and onto the floor; this is the
    // seam that used to be a hardcoded lookup.
    for (const [path, p] of entries) {
      if (!p.floor?.allow?.length) continue;
      expect(restrictedRoleCommands(p.role), `${path}`).toEqual(p.floor.allow);
    }
  });

  it("no floor carries a command that is not a `bsc ` store verb", () => {
    // The confined-surface invariant (#4090). It also catches scraped prose: the generator that first
    // produced these floors put "seeing is not reaching" into the architect's surface, lifted out of a
    // COMMENT, and this shape check is what would have caught it.
    for (const [path, p] of entries) {
      for (const cmd of p.floor?.allow ?? []) {
        expect(cmd, `${path}: '${cmd}' is not a bsc verb`).toMatch(/^bsc [a-z]/);
      }
    }
  });
});

// A persona DECLARES the `bsc` command surfaces it drives, and is held to them
// (`a-persona-declares-its-command-surfaces`, epic `epic-command-surfaces-are-nodes`).
//
// `bsc` sits in the permission model's `mandatory` tier (`data/permissions/base.json`) — always
// allowed, every role, every posture — so before this a worker and a director could reach all ~33
// command surfaces, which is far more than either protocol asks for. The restriction is expressed as
// a DENY of the undeclared complement rather than as an `allow` list, and the difference is the whole
// design; `aWorkerKeepsItsBaselineCommandTiers` below is the test that pins it.
import { describe, it, expect } from "vitest";
import {
  ROLE_DEFAULTS,
  capabilitySurfaces,
  personaSurfaces,
  surfacesFromAllow,
  roleCapability,
  roleDeniedCommands,
  isRestrictedRole,
  mayFileToolingRequest,
  restrictedRoleCommands,
  type SessionRole,
} from "@/shared/lib/session/sessionRoles";

/** A stand-in for `bsc surface list --json`'s ACTIVE rows — the shape the consumer joins against. */
const CATALOG = ["plan", "graph", "ui", "files", "errors", "fleet", "atlas", "teams", "persona", "publish", "logs", "request", "cad"];

describe("surfacesFromAllow — deriving a confined role's surfaces from the list it already carries", () => {
  it("takes the SECOND token, because an allow entry is a command prefix and not a surface name", () => {
    expect(surfacesFromAllow(["bsc ui", "bsc plan brief", "bsc shot preview"])).toEqual(["ui", "plan", "shot"]);
  });

  it("dedupes, so the designer's five loop verbs contribute ONE `loop` surface rather than five", () => {
    expect(surfacesFromAllow(["bsc loop new", "bsc loop say", "bsc loop watch"])).toEqual(["loop"]);
  });

  it("ignores an entry that is not a `bsc` command at all — it names no surface", () => {
    // A role may legitimately allow a non-bsc command; mapping it would invent a surface called `push`.
    expect(surfacesFromAllow(["git push", "bsc ui"])).toEqual(["ui"]);
    expect(surfacesFromAllow(["bsc"])).toEqual([]); // a bare `bsc` names no subcommand
  });

  it("is empty for an absent list rather than throwing", () => {
    expect(surfacesFromAllow(undefined)).toEqual([]);
    expect(surfacesFromAllow(null)).toEqual([]);
  });
});

describe("personaSurfaces — what a role declares", () => {
  it("returns NULL, not [], for a role that declares nothing", () => {
    // The distinction is load-bearing: `null` means UNCONSTRAINED (bsc is in the mandatory tier, so
    // the role reaches everything), while `[]` would read as "drives no surface at all" and, fed to
    // the complement below, would deny the entire CLI to every role not yet declared — the whole
    // fleet, today. A caller that conflates them locks out `triage`, `tester`, `reviewer` and the rest.
    expect(personaSurfaces("triage")).toBeNull();
    expect(personaSurfaces(null)).toBeNull();
    expect(personaSurfaces(undefined)).toBeNull();
  });

  it("returns the explicit list for a role that declares one", () => {
    expect(personaSurfaces("worker")).toEqual(["plan", "graph", "ui", "files", "errors"]);
    expect(personaSurfaces("director")).toContain("fleet");
  });

  it("DERIVES a confined role's list from its allow list rather than reading a second copy", () => {
    // The designer's floor names `bsc ui`, `bsc shot preview`, … and nothing restates those as
    // surfaces. Two copies of one fact drift the first time either is edited alone.
    expect(ROLE_DEFAULTS.designer.surfaces).toBeUndefined();
    expect(personaSurfaces("designer")).toEqual(surfacesFromAllow(ROLE_DEFAULTS.designer.allow));
    expect(personaSurfaces("designer")).toContain("ui");
  });

  it("agrees with the allow list for EVERY confined role — the derivation is not spot-checked", () => {
    const confined = (Object.keys(ROLE_DEFAULTS) as SessionRole[]).filter((r) => isRestrictedRole(r));
    expect(confined.length).toBeGreaterThan(0); // the assertion below is vacuous otherwise
    for (const role of confined) {
      expect(personaSurfaces(role)).toEqual(surfacesFromAllow(restrictedRoleCommands(role)));
    }
  });
});

describe("capabilitySurfaces — read the CAPABILITY, never re-look-up the role", () => {
  it("honours a per-assignment narrowing instead of reading the wider table row", () => {
    // `roleCapability` merges an override onto the role default. Looking the role up again would read
    // the shipped row and silently undo the narrowing — the bug this split exists to prevent.
    const narrowed = roleCapability("worker", { surfaces: ["plan"] });
    expect(capabilitySurfaces(narrowed)).toEqual(["plan"]);
    expect(personaSurfaces("worker")).not.toEqual(["plan"]); // the table row is still the wide one
  });

  it("is null for a capability that declares neither surfaces nor an allow list", () => {
    expect(capabilitySurfaces(roleCapability("triage"))).toBeNull();
    expect(capabilitySurfaces(null)).toBeNull();
  });
});

describe("roleDeniedCommands — the undeclared complement is denied", () => {
  it("denies every ACTIVE surface a declaring role did not name", () => {
    const denies = roleDeniedCommands(roleCapability("worker"), CATALOG);
    expect(denies).toContain("bsc atlas");
    expect(denies).toContain("bsc cad");
    expect(denies).toContain("bsc teams");
  });

  it("does NOT deny a surface the role declared", () => {
    const denies = roleDeniedCommands(roleCapability("worker"), CATALOG);
    for (const surface of ["plan", "graph", "ui", "files", "errors"]) {
      expect(denies).not.toContain(`bsc ${surface}`);
    }
  });

  it("gives the director its own set — the two roles are not interchangeable", () => {
    const denies = roleDeniedCommands(roleCapability("director"), CATALOG);
    expect(denies).not.toContain("bsc fleet");    // its whole job
    expect(denies).not.toContain("bsc publish");
    expect(denies).toContain("bsc graph");        // a worker's surface, not the director's
    expect(denies).toContain("bsc ui");
  });

  it("denies NOTHING extra for an undeclared role, so the undeclared fleet is unaffected", () => {
    const before = roleDeniedCommands(roleCapability("triage"));
    const after = roleDeniedCommands(roleCapability("triage"), CATALOG);
    expect(after).toEqual(before);
  });

  it("FAILS OPEN on an empty catalog rather than denying the whole CLI", () => {
    // The catalog is read from a subprocess, so "could not read it" and "no surfaces" are the same
    // value here. Complementing against nothing must deny nothing — the alternative bricks every
    // session the moment that read fails.
    //
    // Compared against the NO-CATALOG call rather than filtered by prefix: the role gate already
    // emits `bsc ui set`, `bsc persona set` and friends for their own reasons, so a `startsWith("bsc ")`
    // filter would assert those away too and pass for the wrong reason.
    expect(roleDeniedCommands(roleCapability("worker"), [])).toEqual(roleDeniedCommands(roleCapability("worker")));
  });

  it("carries a SPACE in every surface deny, so it can never match the bare `bsc` program", () => {
    // `deny_matches` (crates/bsc-util/src/deny.rs) gives a bare program name program-TOKEN semantics
    // and keeps substring semantics for anything else. A deny of `bsc` alone would kill the entire CLI.
    for (const d of roleDeniedCommands(roleCapability("worker"), CATALOG).filter((x) => x.startsWith("bsc"))) {
      expect(d).toMatch(/^bsc \S/);
    }
  });

  it("emits no duplicate — `bsc request` is denied both as a surface and as the tooling queue", () => {
    const denies = roleDeniedCommands(roleCapability("worker"), CATALOG);
    expect(denies.filter((d) => d === "bsc request")).toHaveLength(1);
    expect(new Set(denies).size).toBe(denies.length);
  });
});

describe("the restriction is a DENY, never an `allow` — the trap this design avoids", () => {
  it("leaves a worker UNCONFINED, so it keeps cargo/npm/git/gh at launch", () => {
    // `allow`'s presence is what flips `isRestrictedRole`, and that suppresses the BASELINE command
    // tiers (`restrictedAllow`). Expressing the surface restriction as an allow list would have taken
    // a worker's build toolchain away with it — the session could no longer run its own gate.
    expect(isRestrictedRole("worker")).toBe(false);
    expect(isRestrictedRole("director")).toBe(false);
    expect(ROLE_DEFAULTS.worker.allow).toBeUndefined();
    expect(ROLE_DEFAULTS.director.allow).toBeUndefined();
  });

  it("still confines the studio roles, which DO mean the allow-list semantics", () => {
    expect(isRestrictedRole("designer")).toBe(true);
    expect(isRestrictedRole("librarian")).toBe(true);
  });
});

describe("the declared sets match what each protocol actually asks for", () => {
  it("a worker drives the stores its protocol names, and NOT the director's fleet verbs", () => {
    const worker = personaSurfaces("worker")!;
    // data/fleet/worker-protocol.md: `bsc graph impl get`, `bsc ui get/set/backing`, `bsc plan …`,
    // `bsc files read`, `bsc errors run`.
    expect(worker.slice().sort()).toEqual(["errors", "files", "graph", "plan", "ui"]);
    // `bsc fleet` appears in that protocol ONLY as the director's `bsc fleet wake`, and the global
    // tooling queue is deliberately the director's escalation — a worker files `bsc plan request`.
    expect(worker).not.toContain("fleet");
    expect(worker).not.toContain("request");
  });

  it("a director keeps the tooling queue, because it is the sanctioned escalation point", () => {
    // `mayFileToolingRequest(director)` is true (#4001), so denying `bsc request` here would
    // contradict the role model and close the only lane a worker's ask can be promoted through.
    expect(personaSurfaces("director")).toContain("request");
    expect(roleDeniedCommands(roleCapability("director"), CATALOG)).not.toContain("bsc request");
  });
});

// ── the surface OPERATOR (`surface-operator-runs-confined-to-its-own-noun`) ────────────────────────
//
// It launched with NO role: `openSurfaceSession` sets a surface pane's model, provider and charter and
// never `setPaneRole`, and a surface pane is not in the fixed studio registry — so it reached the
// launch with the whole `base.json` baseline, build tier included, and ran `cargo run --bin bsc` in
// the tree the running app owns. These are the two properties the new role has to hold, and both were
// FALSE for `tester`, the role its persona nominally declared.
describe("the `operator` role is confined and can reach its own queue", () => {
  it("is CONFINED — which is what suppresses the build tier that let it run cargo", () => {
    expect(isRestrictedRole("operator")).toBe(true);
    // The contrast that motivated a new role rather than reusing one: `tester` is not confined, so
    // every baseline tier (cargo, npm, python) stays auto-runnable on it.
    expect(isRestrictedRole("tester")).toBe(false);
  });

  it("may file a TOOLING request — its entire charter is `bsc request new`", () => {
    expect(mayFileToolingRequest("operator")).toBe(true);
    // And the other half of why `tester` was wrong in BOTH directions: it denies the one command this
    // actor exists to run.
    expect(mayFileToolingRequest("tester")).toBe(false);
    expect(roleDeniedCommands(roleCapability("tester"))).toContain("bsc request");
    // NOT "the deny is absent" — every confined role carries the bare `bsc request` deny alongside its
    // verb-level allows, designer and librarian included, and that shape is the established one. What
    // separates them from `tester` is that the queue is a DECLARED surface, which is what
    // `mayFileToolingRequest` reads and what lifts the deny for the verbs the role actually names.
    expect(personaSurfaces("operator")).toContain("request");
    // `tester` declares NO surfaces at all — it is unconfined, so there is no allow list to derive
    // them from, and that is precisely why the queue stays denied for it.
    expect(personaSurfaces("tester")).toBeNull();
  });

  it("never gains a code-write axis — it reports on a surface, it does not fix it", () => {
    expect(roleCapability("operator").code).toBe("none");
  });

  // THE NOUN IS NOT HERE, AND MUST NOT BE. A bare `bsc` entry is rejected outright by
  // `no floor carries a command that is not a bsc store verb` — an allow list saying all-of-bsc is not
  // a confinement. What the role carries is the CROSS-CUTTING half every operator shares: read your
  // surface, measure what it cost, report it, ask your maintainer. The per-session noun arrives on the
  // generated per-pane profile (`surfaceOperatorProfile`), which is the only thing that can know it.
  it("carries the cross-cutting operator surface, and never a bare `bsc`", () => {
    const allow = restrictedRoleCommands("operator");
    for (const c of ["bsc surface", "bsc request new", "bsc errors run", "bsc mem", "bsc session ask"]) {
      expect(allow).toContain(c);
    }
    // `bsc help` is the CATALOG, and it has to be auto-runnable or the charter names an entry point the
    // session cannot use: a confined role runs exactly this list and STOPS to ask for anything else,
    // which an unattended session reads as a stall. It grants nothing — it prints the noun list.
    expect(allow).toContain("bsc help");
    expect(allow).not.toContain("bsc");
    // Every entry names a verb — the shape the floor guard enforces across all personas.
    for (const c of allow) expect(c).toMatch(/^bsc [a-z]/);
  });
});

// The role capability table may not change by accident (epic `the-persona-is-the-whole-agent`).
//
// WHY A FROZEN FIXTURE RATHER THAN MORE ASSERTIONS. The table's source inverted: it used to be
// `data/permissions/role-capabilities.json`, a single reviewable file whose diff showed every
// capability change; it is now projected from 18 separate persona records. That is the right shape —
// one description of an agent, and a write path that can be clamped — but it costs the property the
// old file had for free: a capability change used to be one obvious line in one obvious file, and it
// is now a field inside whichever persona happened to be edited.
//
// This fixture buys that property back. It is an INDEPENDENT copy of the table, captured at the
// inversion and proven equal to the deleted file on every field at that moment. Any change to a
// persona's floor that moves a role's capability fails here and has to be acknowledged.
//
// ⚠️ WHEN THIS FAILS, THE FIXTURE IS NOT AUTOMATICALLY THE THING TO FIX. Decide first whether the
// capability change was intended. Widening a role is the change this file exists to make visible, so
// "update the fixture until it is green" is precisely the move it is here to prevent.
import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, type RoleCapability, type SessionRole } from "@/shared/lib/session/sessionRoles";
import baseline from "./roleCapabilityBaseline.fixtures.json";

const frozen = baseline.roles as Record<string, RoleCapability>;
const roles = Object.keys(frozen) as SessionRole[];

describe("the role capability table matches its frozen baseline", () => {
  it("covers the same set of roles — none added or dropped unnoticed", () => {
    expect(Object.keys(ROLE_DEFAULTS).sort()).toEqual(roles.slice().sort());
  });

  it.each(roles)("%s carries exactly its baseline capability", (role) => {
    expect(ROLE_DEFAULTS[role]).toEqual(frozen[role]);
  });

  it("no role has been widened on any access axis", () => {
    // Stated separately from the equality check above so a FAILURE READS CORRECTLY. Equality tells you
    // something moved; this tells you it moved in the direction that grants more, which is the half
    // that matters when triaging a red gate under time pressure.
    const rank = { none: 0, read: 1, write: 2 } as const;
    const widened: string[] = [];
    for (const role of roles) {
      // `graph` joins the widening check the moment the axis exists, so the store it governs cannot
      // be handed to a new role the way it was handed to EVERY role before it had a gate at all
      // (`the-algorithms-graph-has-no-write-gate`).
      for (const axis of ["github", "git", "code", "net", "ui", "graph"] as const) {
        const now = rank[ROLE_DEFAULTS[role]?.[axis] as keyof typeof rank] ?? 0;
        const was = rank[frozen[role][axis] as keyof typeof rank] ?? 0;
        if (now > was) widened.push(`${role}.${axis}: ${frozen[role][axis]} → ${ROLE_DEFAULTS[role][axis]}`);
      }
    }
    expect(widened).toEqual([]);
  });

  it("no role has gained a write glob or a harvest root it did not have", () => {
    const gained: string[] = [];
    for (const role of roles) {
      for (const glob of ROLE_DEFAULTS[role]?.writeGlobs ?? []) {
        if (!(frozen[role].writeGlobs ?? []).includes(glob)) gained.push(`${role}.writeGlobs += ${glob}`);
      }
      for (const root of ROLE_DEFAULTS[role]?.harvestRoots ?? []) {
        if (!(frozen[role].harvestRoots ?? []).includes(root)) gained.push(`${role}.harvestRoots += ${root}`);
      }
    }
    expect(gained).toEqual([]);
  });

  it("no CONFINED role has had its command surface lifted or extended", () => {
    // The asymmetric field: `allow` absent means UNCONFINED, so losing it is a widening even though
    // "fewer entries" reads like a narrowing everywhere else in this file.
    const loosened: string[] = [];
    for (const role of roles) {
      const was = frozen[role].allow ?? [];
      if (!was.length) continue;
      const now = ROLE_DEFAULTS[role]?.allow ?? [];
      if (!now.length) { loosened.push(`${role}: confined surface REMOVED — the role is now unconfined`); continue; }
      for (const cmd of now) if (!was.includes(cmd)) loosened.push(`${role}.allow += ${cmd}`);
    }
    expect(loosened).toEqual([]);
  });
});

// The STEWARD is a network's root session — it USES what the network has already built
// (`a-network-gets-a-root-session-that-can-use-what-it-owns`).
//
// WHY THESE ASSERTIONS AND NOT A RENDER TEST. The role's whole content is an AUTHORITY, and an
// authority is invisible until something is refused. These pin the two properties that would be
// expensive to discover the normal way: that the steward is not quietly the surface operator, and
// that "read-only by default" is expressed as an allow-list rather than a deny.
import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, type SessionRole } from "@/shared/lib/session/sessionRoles";

const steward = ROLE_DEFAULTS.steward;
const allow = steward?.allow ?? [];

/** The verbs that CHANGE something the steward can see. */
const MUTATING = ["bsc deploy push", "bsc deploy rollback", "bsc fleet start", "bsc plan status"];

describe("the steward is a distinct role from the surface operator", () => {
  it("exists as its own role", () => {
    expect(steward, "the steward role is projected from src-tauri/data/personas/steward.json").toBeTruthy();
    expect(steward.role).toBe("steward");
  });

  it("is NOT the operator — they are different authorities behind different words", () => {
    // `surface-operator-runs-confined-to-its-own-noun` (verified) uses `operator` for a session
    // confined to ONE `bsc` noun, reporting what that noun COSTS. A steward ranges across a whole
    // domain's finished systems. One word for both would put "may drive the network's deployed
    // machines" and "may measure one CLI" behind the same grant.
    const operator = ROLE_DEFAULTS.operator as typeof steward | undefined;
    expect(operator, "the operator still exists — this is an addition, not a rename").toBeTruthy();
    expect(steward.allow).not.toEqual(operator?.allow);
  });
});

describe("the steward is read-only by DEFAULT", () => {
  it("holds no write on any access axis", () => {
    for (const axis of ["github", "git", "code", "net", "ui", "graph"] as const) {
      expect(steward[axis], `steward.${axis} must not grant write`).not.toBe("write");
    }
  });

  it("can READ what the network can do — the capability surface it exists to report on", () => {
    // Without these it cannot answer its one question, and would have to guess — which is the failure
    // `docs/llm-operator/context.md` demonstrates.
    for (const verb of ["bsc capability", "bsc deploy status", "bsc project list"]) {
      expect(allow, `a steward must be able to run \`${verb}\``).toContain(verb);
    }
  });

  it("does NOT auto-run a mutating verb — so each one stops and asks", () => {
    // THE AUTHORITY MODEL, and the direction is deliberate. A mutating verb is ABSENT from the allow
    // list rather than denied: absent falls through to the default posture's prompt, so the human
    // decides per action, while a deny would make it unreachable even when the user wants it.
    for (const verb of MUTATING) {
      expect(allow, `\`${verb}\` must not auto-run for a steward`).not.toContain(verb);
    }
  });

  it("can still file a tooling request, which is how it reports a gap it cannot close", () => {
    expect(allow).toContain("bsc request new");
  });
});

describe("the role vocabulary stayed coherent", () => {
  it("every allowed verb is a `bsc` verb — the steward's whole surface is the CLI", () => {
    // Like the designer and the architect: the stores are the surface, so a shell escape hatch would
    // be a second, ungoverned way to reach them.
    for (const verb of allow) expect(verb.startsWith("bsc "), `unexpected non-bsc grant: ${verb}`).toBe(true);
  });

  it("does not collide with an existing role name", () => {
    const roles = Object.keys(ROLE_DEFAULTS) as SessionRole[];
    expect(roles.filter((r) => r === "steward")).toHaveLength(1);
    expect(roles).toContain("operator");
  });
});
